insert into public.posts(title,slug,category,summary,content,thumbnail_url,images,published,published_at) values
('엔진오일 교환 시기는 언제인가요?','engine-oil-change','automotive-care','주행거리와 기간, 운전 환경을 함께 확인하면 교환 시기를 이해하기 쉽습니다.',E'## 차량 설명서가 첫 번째 기준입니다\n엔진오일 교환 주기는 차종과 엔진, 사용하는 오일에 따라 다릅니다. 차량 설명서의 주행거리와 기간을 확인하고 먼저 도래하는 기준에 맞춰 점검하세요.\n\n## 짧은 거리만 운전해도 점검이 필요합니다\n짧은 거리의 반복 운행이나 잦은 정체는 차량에 부담을 줄 수 있습니다. 주행거리가 적어도 마지막 교환일을 확인해 주세요.\n\n## 경고등이나 누유가 있다면\n오일 압력 경고등이 켜지거나 누유가 의심되면 안전한 곳에 정차하고 차량 설명서에 따라 조치한 뒤 정비소에 문의하세요. 단순히 오일을 더 넣는 것으로 해결되지 않을 수 있습니다.\n\n## 방문할 때 알려주세요\n차종, 차량 연식, 최근 교환일과 평소 운행 환경을 알려주시면 상태를 확인하고 필요한 정비를 안내합니다.','/board-images/care.svg','{}',true,now()),
('타이어 공기압은 언제 확인해야 하나요?','tire-pressure','automotive-care','한 달에 한 번과 장거리 운행 전, 식은 타이어 상태에서 권장 공기압을 확인하세요.',E'## 권장 수치는 차량에서 확인하세요\n운전석 문 안쪽의 표기나 차량 설명서에 있는 권장 공기압을 확인하세요. 타이어 옆면의 최대 공기압을 차량 권장 수치로 사용하지 마세요.\n\n## 정기적으로, 장거리 운행 전에\n한 달에 한 번 정도와 장거리 운행 전에 확인하는 습관이 도움이 됩니다. 온도 변화가 크거나 공기압 경고등이 켜졌을 때도 확인하세요.\n\n## 타이어가 식었을 때 확인하세요\n주행 직후에는 타이어 온도로 공기압이 높아질 수 있습니다. 차량 설명서에 따라 타이어가 식은 상태에서 측정하세요.\n\n## 계속 공기가 빠진다면\n한쪽 타이어에서 공기가 반복해서 빠지면 손상이나 밸브 문제 등을 점검해야 합니다. 마모와 균열도 함께 살펴보세요.','/board-images/tire.svg','{}',true,now()),
('[구성 예시] 브레이크 소음 점검과 안내','brake-pad-replacement','repair-case','실제 고객의 정비 기록이 아닌 게시물 구성 예시입니다. 실제 사진과 점검 결과를 확인한 뒤 교체해 주세요.',E'## 구성 예시 안내\n이 글은 정비사례의 작성 흐름을 보여주는 예시이며 장성카센터의 실제 작업이나 고객 사례가 아닙니다. 삽입된 이미지는 설명용 그림입니다.\n\n## 고객 증상\n예시: 브레이크를 밟을 때 소리가 난다고 말씀하신 상황을 기록합니다. 발생 시점과 주행 상황을 함께 확인합니다.\n\n## 점검 내용\n예시: 패드와 디스크 상태, 소음 발생 조건을 확인하고 점검 근거를 기록합니다.\n\n## 발견된 문제\n실제 점검으로 확인한 문제와 정상인 항목을 구분해 기록합니다. 확인 전 부품 교체를 단정하지 않습니다.\n\n## 정비 내용\n고객에게 점검 결과와 견적을 설명하고 동의를 받은 실제 작업만 기록합니다.\n\n## 정비 후 안내\n작업 후 확인 결과와 주행 시 주의사항, 다음 점검에 관한 안내를 기록합니다.','/board-images/repair.svg',array['/board-images/inspection.svg','/board-images/repair.svg'],true,now()),
('[구성 예시] 배터리 시동 불량 점검','battery-inspection','repair-case','고객 증상부터 정비 후 안내까지 기록하는 예시입니다. 실제 정비 자료가 준비되면 수정해 주세요.',E'## 구성 예시 안내\n실제 작업 결과가 아닌 작성용 예시입니다. 고객 정보나 실제 정비 사진은 포함되어 있지 않습니다.\n\n## 고객 증상\n예시: 아침 첫 시동이 약하게 느껴지는 상황과 최근 운행 습관을 듣습니다.\n\n## 점검 내용\n배터리와 충전 계통, 단자 상태 등 실제로 확인한 항목을 기록합니다.\n\n## 발견된 문제\n측정값과 점검 결과를 토대로 원인을 설명합니다. 단순히 시동이 약하다는 이유만으로 배터리 교체를 권하지 않습니다.\n\n## 정비 내용\n고객이 동의한 정비와 사용 부품을 기록합니다.\n\n## 정비 후 안내\n확인 결과와 이후 관리 방법을 안내합니다.','/board-images/inspection.svg','{}',true,now()),
('예약정비 문의 안내','booking-guide','news','차량 정보와 증상을 남겨주시면 방문 일정과 필요한 점검을 상담합니다.',E'## 방문 전 차량 증상을 알려주세요\n예약·문의 페이지에서 차종과 증상, 희망 방문일을 남길 수 있습니다.\n\n## 문의 접수와 예약 확정은 다릅니다\n문의 내용을 확인한 뒤 연락드리며, 실제 방문 일정은 상담 후 확정됩니다. 작업 상황과 부품 준비에 따라 일정이 달라질 수 있습니다.\n\n## 확인한 뒤 필요한 정비만\n고객 이야기를 먼저 듣고 점검 후 필요한 정비만 안내합니다. 비용과 작업 시간은 차량 상태를 확인한 뒤 설명합니다.','/board-images/news.svg','{}',true,now()),
('계절이 바뀔 때 확인하면 좋은 점검 항목','seasonal-inspection','news','타이어, 배터리, 냉방 성능을 운행 환경에 맞춰 확인해 보세요.',E'## 타이어 상태부터 확인하세요\n공기압과 마모, 균열을 살펴보세요. 장거리 운행을 앞두고 있다면 여유 있게 점검을 문의해 주세요.\n\n## 배터리는 계절과 관계없이\n시동이 약해지거나 오랜 기간 운행하지 않았다면 상태를 확인하세요. 배터리 문제는 겨울에만 발생하는 것이 아닙니다.\n\n## 에어컨과 기본 안전 항목\n냉방이 약하거나 이상 냄새가 나면 원인을 점검하세요. 와이퍼와 조명 등 안전 항목도 함께 살피면 좋습니다.\n\n## 방문 일정은 상담 후 확정됩니다\n구체적인 비용과 작업 가능 여부는 차량 상태를 확인한 뒤 안내합니다.','/board-images/news.svg','{}',true,now())
insert into public.faq(question,answer,display_order,published) values
('예약 없이 방문해도 되나요?','가능 여부는 당일 작업 상황에 따라 달라집니다. 방문 전 전화 또는 예약 문의로 확인해 주세요.',1,true),
('수입차도 정비 가능한가요?','차종과 작업 항목에 따라 가능 여부가 달라집니다. 차종과 증상을 알려주시면 확인 후 안내합니다.',2,true),
('엔진오일 교환하면서 기본점검도 가능한가요?','차량 상태를 함께 살피는 기본점검을 진행하며, 확인 범위는 방문 시 안내합니다.',3,true),
('중고타이어도 판매하나요?','장성카센터는 중고타이어를 취급하지 않습니다. 차량에 맞는 새 타이어는 상담 후 안내합니다.',4,true),
('정비 비용을 전화로 정확하게 알 수 있나요?','차종과 증상으로 기본적인 상담은 가능하지만 정확한 비용은 차량 상태와 필요한 부품을 점검한 뒤 안내합니다. 작업 내용과 견적을 설명하고 동의 후 정비합니다.',5,true),
('타이어 교체 후 얼라인먼트도 가능한가요?','차종과 작업 상황에 따라 가능 여부를 확인해야 합니다. 방문 전에 문의해 주시면 필요한 점검과 작업 가능 여부를 안내합니다.',6,true),
('정비 시간은 얼마나 걸리나요?','차량 상태와 작업 항목에 따라 다릅니다. 점검 후 예상 시간을 안내합니다.',7,true),
('타이어는 어떤 제품을 취급하나요?','장성카센터는 금호타이어 용담점입니다. 차량과 운전 환경에 맞는 제품은 상담 후 안내합니다.',8,true),
('정비 전에 견적을 받을 수 있나요?','점검 결과와 필요한 작업을 설명하고 고객 동의를 받은 뒤 정비를 진행합니다.',9,true);
